const STY = (bg) => `position:absolute;left:100px;width:740px;display:flex;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.4);background:${bg};color:#ffffff;font-weight:800;line-height:1;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:100px;height:160px;font-size:72px;opacity:0">74 SLASH COMMANDS</div>
  <div id="c1" style="${STY(B2)}top:330px;height:130px;font-size:48px;opacity:0">DESIGN REVIEWS</div>
  <div id="c2" style="${STY(B1)}top:530px;height:130px;font-size:48px;opacity:0">QA TESTING</div>
  <div id="c3" style="${STY(B2)}top:730px;height:130px;font-size:48px;opacity:0">RELEASE MANAGEMENT</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:10;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 260 L470 330" />
    <path id="l1" d="M470 460 L470 530" />
    <path id="l2" d="M470 660 L470 730" />
  </svg>
`;

const items = [0, 1, 2, 3].map(i => root.querySelector(`#c${i}`));
const paths = [0, 1, 2].map(i => {
  const p = root.querySelector(`#l${i}`);
  const len = p.getTotalLength();
  p.style.strokeDasharray = len;
  p.style.strokeDashoffset = len;
  return { el: p, len };
});

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Cards timing: 0.0, 0.8, 1.6, 2.4
  items.forEach((el, i) => {
    const s = spr(tf, i * 0.8, 0.85, 10);
    el.style.opacity = clamp(s * 1.5);
    const y = lerp(40, 0, E_OUT(clamp(s)));
    const sc = lerp(0.85, 1, s);
    el.style.transform = `translateY(${y}px) scale(${sc})`;
  });

  // Paths timing: 0.4, 1.2, 2.0
  paths.forEach((path, i) => {
    const start = 0.4 + (i * 0.8);
    const prog = clamp((tf - start) * 2.5);
    path.el.style.strokeDashoffset = path.len * (1 - E_INOUT(prog));
    path.el.style.opacity = prog * 0.4;
  });
}
